package org.vowen.app

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.launch

@Composable
fun NativeWikiEditor(state:WikiState,isAdmin:Boolean,ru:Boolean,onClose:()->Unit){
 val scope=rememberCoroutineScope();val enabled=isAdmin&&!state.busy;var preview by remember{mutableStateOf(false)};var references by remember{mutableStateOf<Map<String,List<ReferenceEntry>>>(emptyMap())};var filter by remember{mutableStateOf("")};var history by remember{mutableStateOf<List<WikiRevisionView>>(emptyList())};var old by remember{mutableStateOf<WikiRevisionView?>(null)};var historyOffset by remember{mutableIntStateOf(0)};var confirmReload by remember{mutableStateOf(false)}
 LaunchedEffect(state){try{references=listOf("practices","poses","devices").associateWith{state.api.references(it)}}catch(_:Exception){state.error="REFERENCE_UNAVAILABLE"}}
 if(confirmReload)AlertDialog(onDismissRequest={confirmReload=false},title={Text(if(ru)"Загрузить свежую версию?" else "Load current version?")},text={Text(if(ru)"Ваши несохранённые изменения будут заменены только после успешной загрузки." else "Your unsaved changes will be replaced only after a successful reload.")},confirmButton={TextButton(onClick={confirmReload=false;state.saved?.uid?.let{uid->scope.launch{state.edit(uid)}}}){Text(if(ru)"Загрузить" else "Reload")}},dismissButton={TextButton(onClick={confirmReload=false}){Text(if(ru)"Остаться" else "Stay")}})
 fun update(document:WikiDocument){state.draft=document}
 Column(Modifier.fillMaxWidth(),verticalArrangement=Arrangement.spacedBy(16.dp)){
  TextButton(onClick=onClose,enabled=!state.busy){Text(if(ru)"← К библиотеке" else "← Back to library")}
  Text(if(ru)"Редактор материала" else "Page editor",style=MaterialTheme.typography.headlineMedium)
  if(!isAdmin)Text(if(ru)"Права редактирования отозваны. Текст остался в этом окне." else "Editing access revoked. Your text remains here.")
  if(state.saved==null){WikiNativeSelect(if(ru)"Вид материала" else "Page type",state.kind,listOf("article" to if(ru)"Статья" else "Article","encyclopedia" to if(ru)"Энциклопедия" else "Encyclopedia"),enabled){state.kind=it};if(state.kind=="encyclopedia"){WikiNativeSelect(if(ru)"Справочник" else "Catalogue",state.mainKind,listOf("practices" to if(ru)"Практики" else "Practices","poses" to if(ru)"Позы" else "Poses","devices" to if(ru)"Девайсы" else "Devices"),enabled){state.mainKind=it;state.mainUid=null};WikiNativeSelect(if(ru)"Основной объект" else "Main reference",state.mainUid?:"",references[state.mainKind].orEmpty().map{it.uid to it.name},enabled){state.mainUid=it}}}
  OutlinedTextField(state.draft.title,{update(state.draft.copy(title=it.take(160)))},label={Text(if(ru)"Название" else "Title")},enabled=enabled,modifier=Modifier.fillMaxWidth())
  WikiNativeSelect(if(ru)"Раздел" else "Section",state.draft.section_uid,state.tree?.sections.orEmpty().map{it.uid to it.title},enabled){update(state.draft.copy(section_uid=it))}
  OutlinedTextField(state.draft.summary?:"",{update(state.draft.copy(summary=it.take(600)))},label={Text(if(ru)"Краткое описание" else "Summary")},enabled=enabled,modifier=Modifier.fillMaxWidth())
  Row{TextButton(onClick={preview=!preview}){Text(if(ru)"Предпросмотр" else "Preview")};TextButton(onClick={update(state.draft.copy(body=(state.draft.body?:"")+"\n## "))},enabled=enabled){Text("H2")};TextButton(onClick={update(state.draft.copy(body=(state.draft.body?:"")+"\n- "))},enabled=enabled){Text("•")};TextButton(onClick={update(state.draft.copy(body=(state.draft.body?:"")+"**text**"))},enabled=enabled){Text("B")}}
  if(preview)WikiMarkdownBody(state.draft.body?:"")else OutlinedTextField(state.draft.body?:"",{update(state.draft.copy(body=it.take(100000)))},label={Text(if(ru)"Текст · Markdown" else "Body · Markdown")},enabled=enabled,minLines=8,modifier=Modifier.fillMaxWidth())
  var related by remember{mutableStateOf(false)};TextButton(onClick={related=!related}){Text(if(ru)"Связанные справочники" else "Related references")}
  if(related){OutlinedTextField(filter,{filter=it},label={Text(if(ru)"Поиск записи" else "Find reference")},modifier=Modifier.fillMaxWidth());listOf("practices","poses","devices").forEach{kind->Text(when(kind){"practices"->if(ru)"Практики" else "Practices";"poses"->if(ru)"Позы" else "Poses";else->if(ru)"Девайсы" else "Devices"});val selected=when(kind){"practices"->state.draft.practice_uids.orEmpty();"poses"->state.draft.pose_uids.orEmpty();else->state.draft.device_uids.orEmpty()};references[kind].orEmpty().filter{it.name.contains(filter,true)}.forEach{entry->Row{Checkbox(entry.uid in selected,onCheckedChange={checked->val ids=if(checked)(selected+entry.uid).distinct().take(50)else selected-entry.uid;update(when(kind){"practices"->state.draft.copy(practice_uids=ids);"poses"->state.draft.copy(pose_uids=ids);else->state.draft.copy(device_uids=ids)})},enabled=enabled);Text(entry.name)}}}}
  var extras by remember{mutableStateOf(false)};TextButton(onClick={extras=!extras}){Text(if(ru)"Источники и миниатюра" else "Sources and thumbnail")}
  if(extras){OutlinedTextField(state.draft.thumbnail?:"",{update(state.draft.copy(thumbnail=it.take(500).ifBlank{null}))},label={Text(if(ru)"Локальная миниатюра" else "Local thumbnail")},enabled=enabled,modifier=Modifier.fillMaxWidth());state.draft.sources.orEmpty().forEachIndexed{i,s->OutlinedTextField(s.name?:"",{value->update(state.draft.copy(sources=state.draft.sources.orEmpty().mapIndexed{index,source->if(index==i)source.copy(name=value.take(160))else source}))},label={Text(if(ru)"Название источника" else "Source name")},enabled=enabled,modifier=Modifier.fillMaxWidth());OutlinedTextField(s.url,{value->update(state.draft.copy(sources=state.draft.sources.orEmpty().mapIndexed{index,source->if(index==i)source.copy(url=value.take(2000))else source}))},label={Text("https://")},enabled=enabled,modifier=Modifier.fillMaxWidth());TextButton(onClick={update(state.draft.copy(sources=state.draft.sources.orEmpty().filterIndexed{index,_->index!=i}))},enabled=enabled){Text(if(ru)"Удалить источник" else "Remove source")}};TextButton(onClick={update(state.draft.copy(sources=state.draft.sources.orEmpty()+WikiSource(url="")))},enabled=enabled&&state.draft.sources.orEmpty().size<20){Text(if(ru)"Добавить источник" else "Add source")}}
  Button(onClick={scope.launch{state.save()}},enabled=enabled&&state.draft.section_uid.isNotBlank()&&(state.kind=="article"||state.mainUid!=null)){Text(if(ru)"Сохранить черновик" else "Save draft")}
  Button(onClick={scope.launch{state.save(true)}},enabled=enabled&&state.draft.title.isNotBlank()&&!state.draft.body.isNullOrBlank()&&state.saved?.archived_at==null){Text(if(ru)"Опубликовать" else "Publish")}
  state.saved?.let{saved->TextButton(onClick={scope.launch{state.archive()}},enabled=enabled&&!state.dirty){Text(if(saved.archived_at==null)(if(ru)"В архив" else "Archive")else(if(ru)"Восстановить" else "Restore"))};TextButton(onClick={scope.launch{state.action{history=state.api.history(saved.uid);historyOffset=0}}}){Text(if(ru)"История редакций" else "Revision history")};if(state.error!=null)TextButton(onClick={if(state.dirty)confirmReload=true else scope.launch{state.edit(saved.uid)}},enabled=!state.busy){Text(if(ru)"Загрузить свежую версию" else "Load current version")};if(history.isNotEmpty()){history.forEach{r->TextButton(onClick={old=r}){Text(r.created_at+" · "+r.document.title)}};Row{TextButton(onClick={scope.launch{state.action{historyOffset=(historyOffset-50).coerceAtLeast(0);history=state.api.history(saved.uid,historyOffset)}}},enabled=historyOffset>0){Text("←")};TextButton(onClick={scope.launch{state.action{historyOffset+=50;history=state.api.history(saved.uid,historyOffset)}}},enabled=history.size==50){Text("→")}}}}
  old?.let{Text(it.document.title,style=MaterialTheme.typography.headlineSmall);WikiMarkdownBody(it.document.body?:"")}
 }
}

@Composable internal fun WikiNativeSelect(label:String,selected:String,items:List<Pair<String,String>>,enabled:Boolean=true,onSelect:(String)->Unit){var open by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={open=true},enabled=enabled,modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(label+": "+(items.find{it.first==selected}?.second?:"—"))};DropdownMenu(expanded=open,onDismissRequest={open=false},modifier=Modifier.heightIn(max=340.dp)){items.forEach{(id,name)->DropdownMenuItem(text={Text(name)},onClick={onSelect(id);open=false})}}}}
